$path='C:/Program Files/Ampps'
# Fix httpd-ssl.conf placeholders
$ssl='c:\Program Files\Ampps\apache\conf\extra\httpd-ssl.conf'
$content=Get-Content $ssl -Raw
if ($content -match '\{\$path\}') {
  Copy-Item $ssl "$ssl.bak_$(Get-Date -Format yyyyMMddHHmmss)" -Force
  $fixed=$content -replace '\{\$path\}',[regex]::Escape($path).Replace('\','/') -replace [regex]::Escape([regex]::Escape($path).Replace('\','/')),$path
